shortcuts.codeOnPrepare:
"use strict";

var TRAILING_URL = /\s*(https?:\/\/\S+)\s*$/;

function stripQuotePair(s) {
  var pairs = [['"', '"'], ["“", "”"]];
  for (var i = 0; i < pairs.length; i++) {
    var open = pairs[i][0];
    var close = pairs[i][1];
    if (s.length >= 2 && s.charAt(0) === open && s.charAt(s.length - 1) === close) {
      return s.slice(1, -1);
    }
  }
  return s;
}

function parseShared(text, subject) {
  var body = String(text || "");
  var url = "";
  var m = TRAILING_URL.exec(body);
  if (m) {
    url = m[1];
    body = body.slice(0, m.index);
  }
  var quote = stripQuotePair(body.trim()).trim();
  return {
    quote: quote,
    url: url,
    subject: String(subject || "").trim(),
  };
}

function escapeHtml(s) {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function stripFragment(url) {
  var i = url.indexOf("#");
  return i === -1 ? url : url.slice(0, i);
}

function hostOf(url) {
  var m = /^https?:\/\/([^\/?#:]+)/i.exec(url);
  return m ? m[1] : "";
}

var NAMED_ENTITIES = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " " };

function decodeEntities(s) {
  return s.replace(/&(#x[0-9a-f]+|#[0-9]+|[a-z]+);/gi, function (all, code) {
    var lower = code.toLowerCase();
    if (lower.charAt(0) === "#") {
      var n = lower.charAt(1) === "x" ? parseInt(lower.slice(2), 16) : parseInt(lower.slice(1), 10);
      return isNaN(n) || n > 0x10ffff ? all : String.fromCodePoint(n);
    }
    return NAMED_ENTITIES.hasOwnProperty(lower) ? NAMED_ENTITIES[lower] : all;
  });
}

function extractTitle(html) {
  var m = /<title[^>]*>([\s\S]*?)<\/title>/i.exec(String(html || ""));
  if (!m) return "";
  return decodeEntities(m[1]).replace(/\s+/g, " ").trim();
}

function usableSubject(subject) {
  var s = String(subject || "").trim();
  return /https?:\/\//i.test(s) ? "" : s;
}

function buildSource(url, title) {
  if (!/^https?:\/\//i.test(url)) return "";
  var label = title || hostOf(url);
  return '<a href="' + escapeHtml(url) + '">' + escapeHtml(label) + "</a>";
}

var REFRESH_MARGIN_MS = 60 * 1000;

function tokenIsExpired(expiresAt, now) {
  var t = parseInt(expiresAt, 10);
  if (isNaN(t)) return true;
  return now >= t - REFRESH_MARGIN_MS;
}

function tokenUpdateFromResponse(json, now, currentRefreshToken) {
  return {
    accessToken: json.access_token,
    refreshToken: json.refresh_token || currentRefreshToken,
    expiresAt: String(now + json.expires_in * 1000),
  };
}

function buildQuoteBody(quote, source, state) {
  var body = { type: "quote", quote: escapeHtml(quote), state: state };
  if (source) body.source = source;
  return body;
}

if (typeof module !== "undefined") {
  module.exports = {
    parseShared: parseShared,
    escapeHtml: escapeHtml,
    stripFragment: stripFragment,
    hostOf: hostOf,
    extractTitle: extractTitle,
    buildSource: buildSource,
    usableSubject: usableSubject,
    tokenIsExpired: tokenIsExpired,
    tokenUpdateFromResponse: tokenUpdateFromResponse,
    buildQuoteBody: buildQuoteBody,
  };
}

var TOKEN_URL = "https://api.tumblr.com/v2/oauth2/token";

function pendingText(p) {
  return p.url ? p.quote + "\n" + p.url : p.quote;
}

function failAndAbort(message, pending) {
  if (pending) copyToClipboard(pendingText(pending));
  showToast(message);
  abort();
}

function loadPending() {
  var sharedText = getVariable("shared_text");
  if (sharedText.trim() !== "") {
    var parsed = parseShared(sharedText, getVariable("shared_title"));
    setVariable("tumblr_pending", JSON.stringify(parsed));
    return parsed;
  }
  var raw = getVariable("tumblr_pending");
  return raw ? JSON.parse(raw) : null;
}

function refreshTokenIfNeeded(pending) {
  if (!tokenIsExpired(getVariable("tumblr_token_expires_at"), Date.now())) return;
  var result = sendHttpRequest(TOKEN_URL, {
    method: "POST",
    formData: {
      grant_type: "refresh_token",
      refresh_token: getVariable("tumblr_refresh_token"),
      client_id: getVariable("tumblr_client_id"),
      client_secret: getVariable("tumblr_client_secret"),
    },
  });
  if (result.status === "success") {
    var t = tokenUpdateFromResponse(JSON.parse(result.response.body), Date.now(), getVariable("tumblr_refresh_token"));
    setVariable("tumblr_access_token", t.accessToken);
    setVariable("tumblr_refresh_token", t.refreshToken);
    setVariable("tumblr_token_expires_at", t.expiresAt);
    return;
  }
  if (result.status === "httpError") {
    failAndAbort("トークン更新失敗 " + result.response.statusCode + " " + String(result.response.body).slice(0, 60), pending);
  }
}

function resolveTitle(pending) {
  var subject = usableSubject(pending.subject);
  if (subject) return subject;
  if (!pending.url) return "";
  var result = sendHttpRequest(stripFragment(pending.url), { method: "GET" });
  return result.status === "success" ? extractTitle(result.response.body) : "";
}

var pending = loadPending();
if (!pending || !pending.quote) {
  failAndAbort("引用する本文がありません", null);
}
refreshTokenIfNeeded(pending);
var source = buildSource(pending.url, resolveTitle(pending));
setVariable("post_body", JSON.stringify(buildQuoteBody(pending.quote, source, getVariable("tumblr_post_state"))));

shortcuts.codeOnFailure:
var raw = getVariable("tumblr_pending");
if (raw) {
  var p = JSON.parse(raw);
  copyToClipboard(p.url ? p.quote + "\n" + p.url : p.quote);
}
if (response) {
  showToast("Tumblr " + response.statusCode + " " + String(response.body).slice(0, 60));
} else {
  showToast("通信エラー " + networkError);
}
